import{_ as a,c as t,o as r,ag as n}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"AI app coverage and ownership map","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/coverage-map.md","filePath":"applied-ai/coverage-map.md"}'),i={name:"applied-ai/coverage-map.md"};function o(s,e,d,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-app-coverage-and-ownership-map" tabindex="-1">AI app coverage and ownership map <a class="header-anchor" href="#ai-app-coverage-and-ownership-map" aria-label="Permalink to “AI app coverage and ownership map”">​</a></h1><h2 id="beginner-javascript-route-added-2026-10-28" tabindex="-1"><span class="hub-section-number">1 </span>Beginner JavaScript route added 2026-10-28 <a class="header-anchor" href="#beginner-javascript-route-added-2026-10-28" aria-label="Permalink to “1 Beginner JavaScript route added 2026-10-28”">​</a></h2><p><a href="./">Build AI Apps — JavaScript First</a> is now the primary beginner entry. Existing sections below describe the deeper retained Python/reference mechanisms, not prerequisites to a first chatbot.</p><table tabindex="0"><thead><tr><th>New owner</th><th>Implemented reference / remaining work</th></tr></thead><tbody><tr><td><a href="./javascript/first-call.html">JS foundations and chatbot</a>, <a href="./javascript/chatbot.html">app lesson</a></td><td>Runnable console/HTTP/browser simulation and optional fixed Responses adapter; streaming/React/auth/persistent conversations remain learner extensions</td></tr><tr><td><a href="./javascript/structured-output.html">Structured output</a>, <a href="./javascript/tools-workflows.html">tools</a>, <a href="./javascript/rag.html">RAG</a></td><td>Checked synthetic classification/quotes, public read dispatch, proposal-only state and lexical retrieval; generated classifier/tool loop/full cited RAG/embeddings remain integration practice</td></tr><tr><td><a href="./javascript/mcp.html">MCP</a>, <a href="./javascript/stateful-workflows.html">graphs</a></td><td>Actual pinned JS SDK stdio tool/resource/prompt and RAM interruption/resume fixtures; trusted write approval, durable state and desktop/HTTP host integration remain separate</td></tr><tr><td><a href="./javascript/extensions.html">Extensions</a></td><td>Python/hosted-store/n8n/multimedia/A2A decision guide and optional A2A exercise; no A2A or multimedia service implementation claimed</td></tr><tr><td><a href="./../practice/applied-ai/javascript-assistant.html">Practice</a></td><td>JS-00–09 specifications; all independent learner work outstanding</td></tr></tbody></table><p><a href="./javascript/verification.html">Verification record</a> states what actually ran. <a href="./../ai-assisted-engineering/">AI for Software Development</a> is the separate coding workflow path, including bug and feature references.</p><h2 id="retained-deeper-coverage" tabindex="-1"><span class="hub-section-number">2 </span>Retained deeper coverage <a class="header-anchor" href="#retained-deeper-coverage" aria-label="Permalink to “2 Retained deeper coverage”">​</a></h2><p>Coverage below is based on actual explanations, contracts and worked source/tests, not headings alone. <strong>Confirmed component coverage</strong> means the boundary is taught and inspectable; it does not mean a full product, live provider or learner outcome was demonstrated. “Expanded” marks this round&#39;s connecting explanations; “new” marks the previously absent n8n material.</p><p>Prerequisites are typed functions, data/JSON validation, current application identity, owned async I/O and basic HTTP/transactions where used. <a href="./../python-for-ai/">Python prerequisites</a> and the completed Node.js/CS courses retain those owners. Shared foundations precede RAG and tools; n8n begins with synthetic manual input rather than a model or deployed agent.</p><h2 id="shared-foundations" tabindex="-1"><span class="hub-section-number">3 </span>Shared foundations <a class="header-anchor" href="#shared-foundations" aria-label="Permalink to “3 Shared foundations”">​</a></h2><h3 id="model-integration-structured-output-and-tool-contracts" tabindex="-1"><span class="hub-section-number">3.1 </span>Model integration, structured output and tool contracts <a class="header-anchor" href="#model-integration-structured-output-and-tool-contracts" aria-label="Permalink to “3.1 Model integration, structured output and tool contracts”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/model-sdk.html">SDK boundary</a>, <a href="./../python-for-ai/token-budgets.html">tokens</a>, <a href="./../python-for-ai/model-streaming.html">streaming</a>, <a href="./../python-for-ai/tool-boundaries.html">tools</a>. Confirmed applied/intermediate component coverage; <a href="./shared/">shared index</a> reconciles the order.</p><p><strong>Inspected evidence:</strong> real SDK/mock-transport serialization, required/extra-field schemas, refusal/incomplete/error vocabulary, complete call arguments and current-principal dispatch; client/stream cancellation and token/body-limit distinctions. Valid JSON is neither truth nor permission. The provider tool loop remains a separately specified adapter, not secretly implemented by the read dispatcher.</p><p><strong>Practice:</strong> existing P-337 prerequisites, P-334 answer boundary, P-335 tool stages; <a href="./../practice/applied-ai/chapters/">relocated chapter exercises</a>. Offline fixtures do not measure model availability/quality.</p><h3 id="state-security-evaluation-observability-and-data-handling" tabindex="-1"><span class="hub-section-number">3.2 </span>State, security, evaluation, observability and data handling <a class="header-anchor" href="#state-security-evaluation-observability-and-data-handling" aria-label="Permalink to “3.2 State, security, evaluation, observability and data handling”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/history-and-workflows.html">history</a>, <a href="./../python-for-ai/prompt-injection-boundaries.html">task injection scope</a>, <a href="./../python-for-ai/source-and-output-security.html">sources/output sinks</a>, <a href="./../python-for-ai/evaluation-lab.html">evaluation</a>, <a href="./../python-for-ai/evaluation-measurements.html">measurements</a>, <a href="./../python-for-ai/workflow-diagnostics.html">safe traces</a>, <a href="./../python-for-ai/provider-data-lifecycle.html">provider lifecycle</a>. Confirmed applied coverage, shared across both tracks.</p><p><strong>Inspected evidence:</strong> complete history windows and lossy-summary counterexample, hostile tool content with zero out-of-task reads, same-ID tenant isolation, current reviewed source/digest gates, fixed safe output sink, authored case/slice/label ledgers, separate schema/semantic/receipt gates, unknown usage and projected traces. Roles/serialization do not guarantee injection immunity. Retention/deletion applies to derivatives and provider features, not only source rows.</p><p><strong>Practice:</strong> P-334/P-335 shared evidence/rubric, optional chapter refinements. Actual authentication UI, provider policy/account settings, native browser behavior and representative semantic measurements remain separate observations.</p><h2 id="rag" tabindex="-1"><span class="hub-section-number">4 </span>RAG <a class="header-anchor" href="#rag" aria-label="Permalink to “4 RAG”">​</a></h2><h3 id="parsing-normalization-chunks-metadata-and-provenance" tabindex="-1"><span class="hub-section-number">4.1 </span>Parsing, normalization, chunks, metadata and provenance <a class="header-anchor" href="#parsing-normalization-chunks-metadata-and-provenance" aria-label="Permalink to “4.1 Parsing, normalization, chunks, metadata and provenance”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/document-processing.html">extraction</a>, <a href="./../python-for-ai/retrieval-context.html">evidence</a>. Confirmed bounded text/CSV baseline plus format/chunk-policy reasoning; PDF/OCR/HTML adapters optional when needed.</p><p><strong>Inspected evidence:</strong> strict bytes/dialect/quoting/leading-zero behavior, normalized versus raw offsets/hash, source/extractor/locator/span identity and limits, overlap/structure tradeoffs, exact current-source reconstruction. Code-point chunks do not claim token fit or semantic completeness. Complex parsing needs isolation and fidelity review.</p><p><strong>Practice:</strong> <a href="./../practice/applied-ai/rag-assistant.html#rag-1-ingestion-and-lexical-baseline">RAG-1</a>, original extraction/span exercises. A structure-aware comparison is required practice, not a fabricated quality result.</p><h3 id="embeddings-indexing-retrieval-filtering-hybrid-and-reranking" tabindex="-1"><span class="hub-section-number">4.2 </span>Embeddings, indexing, retrieval, filtering, hybrid and reranking <a class="header-anchor" href="#embeddings-indexing-retrieval-filtering-hybrid-and-reranking" aria-label="Permalink to “4.2 Embeddings, indexing, retrieval, filtering, hybrid and reranking”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/embeddings-and-similarity.html">similarity/hybrid</a>, <a href="./../python-for-ai/vector-storage-lifecycle.html">vector lifecycle</a>, <a href="./../python-for-ai/retrieval-pipeline.html">pipeline</a>. Confirmed intermediate components; reading order now places storage/lifecycle before full composition.</p><p><strong>Inspected evidence:</strong> compatible spaces and finite/zero handling, lexical Jaccard versus semantic fixture, rank fusion rather than score addition, current ACL/version filtering before limits, original-query branch, bounded pair scorer and deterministic ties. Exact SQLite scan is not ANN; hand vectors are not embeddings quality; lexical pair scoring is not a learned reranker.</p><p><strong>Practice:</strong> <a href="./../practice/applied-ai/rag-assistant.html#rag-2-compatible-indexing-hybrid-and-reranking">RAG-2</a>, comparing one fixed permitted corpus and explicit k/thresholds/labels. Production sparse/ANN/learned adapters remain optional until measured need.</p><h3 id="context-answers-citations-abstention-and-evaluation" tabindex="-1"><span class="hub-section-number">4.3 </span>Context, answers, citations, abstention and evaluation <a class="header-anchor" href="#context-answers-citations-abstention-and-evaluation" aria-label="Permalink to “4.3 Context, answers, citations, abstention and evaluation”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/retrieval-context.html">evidence/citations</a>, <a href="./../python-for-ai/retrieval-pipeline.html">pipeline</a>, <a href="./rag/answering-and-failures.html">new composition explanation</a>, <a href="./../python-for-ai/evaluation-lab.html">evaluation</a>, <a href="./../python-for-ai/retrieval-debugging.html">retrieval debugging</a>. Expanded integration contract, with existing component coverage retained.</p><p><strong>Inspected evidence:</strong> final messages/schema counted, source/version recheck, greedy selection/source caps, unknown IDs/quotes rejected, genuine-but-contradictory quote counterexample, no-evidence versus outage/budget loss, Recall/MRR/nDCG and support rubric, duplicate crowding and oracle-context diagnosis. Simpler lexical/direct-query alternatives are explicit in the <a href="./rag/">RAG home</a>.</p><p><strong>Practice:</strong> <a href="./../practice/applied-ai/rag-assistant.html">RAG-3/4</a>, refining P-334. A multi-chunk repository and generated-answer adapter are learner integrations; the label classifier/context builder is not a complete assistant.</p><h3 id="updates-deletion-access-control-and-derived-artifacts" tabindex="-1"><span class="hub-section-number">4.4 </span>Updates, deletion, access control and derived artifacts <a class="header-anchor" href="#updates-deletion-access-control-and-derived-artifacts" aria-label="Permalink to “4.4 Updates, deletion, access control and derived artifacts”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/vector-storage-lifecycle.html">persistent lifecycle</a>, <a href="./../python-for-ai/cache-and-batch.html">cache/batch identity</a>, <a href="./../python-for-ai/provider-data-lifecycle.html">provider derivatives</a>. Confirmed intermediate local mechanism and operational design.</p><p><strong>Inspected evidence:</strong> immediate stale-vector hiding, ACL filtering without re-embedding, raced/incomplete generation refusal, atomic activation, delete across generations, source revalidation and logical-versus-physical erasure distinctions. Restore/reingestion needs tombstones and in-flight publication fencing where required; one DELETE is not complete erasure.</p><p><strong>Practice:</strong> RAG-4 and retained P-334 lifecycle cases. Local file/reopen tests establish narrower behavior than backup/provider deletion or hosted in-flight revocation guarantees.</p><h2 id="agent-workflows" tabindex="-1"><span class="hub-section-number">5 </span>Agent workflows <a class="header-anchor" href="#agent-workflows" aria-label="Permalink to “5 Agent workflows”">​</a></h2><h3 id="fixed-orchestration-versus-agent-directed-steps" tabindex="-1"><span class="hub-section-number">5.1 </span>Fixed orchestration versus agent-directed steps <a class="header-anchor" href="#fixed-orchestration-versus-agent-directed-steps" aria-label="Permalink to “5.1 Fixed orchestration versus agent-directed steps”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/tool-workflow-state.html">tool state</a>, <a href="./../python-for-ai/graph-memory.html">graph framework</a>, <a href="./workflows/">workflow home</a>. Expanded autonomy/routing distinction; one framework remains optional.</p><p><strong>Inspected evidence:</strong> finite named routes, bounded temporary-read retries, terminal states, application-owned checked outcome, scoped RAM graph snapshots and single/multi-agent tradeoffs. A bounded lookup/finish proposal contract is explained; no live autonomous model loop is claimed.</p><p><strong>Practice:</strong> <a href="./../practice/applied-ai/resumable-workflow.html#wf-1-fixed-read-propose-validate">WF-1</a>, P-335 baseline comparison. Multi-agent coordination is optional and needs measured benefit plus independent aggregate limits.</p><h3 id="persisted-artifacts-approvals-receipts-partial-failure-and-recovery" tabindex="-1"><span class="hub-section-number">5.2 </span>Persisted artifacts, approvals, receipts, partial failure and recovery <a class="header-anchor" href="#persisted-artifacts-approvals-receipts-partial-failure-and-recovery" aria-label="Permalink to “5.2 Persisted artifacts, approvals, receipts, partial failure and recovery”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/tool-workflow-state.html">state/CAS</a>, <a href="./../python-for-ai/approved-writes.html">approved writes</a>, <a href="./../python-for-ai/provenance-and-oversight.html">audit</a>, <a href="./workflows/resumable-runs.html">resumable runs</a>. Existing local implementations plus expanded whole-run integration design.</p><p><strong>Inspected evidence:</strong> real SQLite revisions/reopen/stale save, exact command digest/principal/expiry, current resource version, atomic local effect+receipt and same-key replay/rollback. Artifact references, staging transaction, unknown remote outcome and concurrent claim/fencing responsibilities are explicit; independent transactions do not compose automatically.</p><p><strong>Practice:</strong> <a href="./../practice/applied-ai/resumable-workflow.html">WF-2/3</a>, exact restart/revoke/lost-response evidence. Trusted human approval UI, complete artifact runner and distributed/remote reconciliation remain implementation tasks, not missing explanations.</p><h3 id="cancellation-retry-observability-and-resource-ceilings" tabindex="-1"><span class="hub-section-number">5.3 </span>Cancellation, retry, observability and resource ceilings <a class="header-anchor" href="#cancellation-retry-observability-and-resource-ceilings" aria-label="Permalink to “5.3 Cancellation, retry, observability and resource ceilings”">​</a></h3><p><strong>Owner/depth:</strong> <a href="./../python-for-ai/model-work-budgets.html">admission/retries</a>, <a href="./../python-for-ai/tool-workflow-state.html#whole-run-limits-and-a-serializable-checkpoint">workflow budget</a>, <a href="./../python-for-ai/model-economics.html">shared reservations</a>, <a href="./../python-for-ai/workflow-diagnostics.html">trace diagnostics</a>. Confirmed local components and expanded restart ownership.</p><p><strong>Inspected evidence:</strong> active/waiting caps, server-minimum/defer policy, nonretryable ambiguous stream/write failures, immutable remaining calls/bytes, UTC-versus-monotonic expiry, known/unknown spend reservation and safe events. Steps, time, memory and money are distinct; a graph recursion limit or one-process gate is not a global guarantee.</p><p><strong>Practice:</strong> <a href="./../practice/applied-ai/resumable-workflow.html#wf-4-time-retries-budgets-and-evaluation">WF-4</a>. Representative task-quality and real provider/production trace evidence stay separate.</p><h2 id="n8n" tabindex="-1"><span class="hub-section-number">6 </span>n8n <a class="header-anchor" href="#n8n" aria-label="Permalink to “6 n8n”">​</a></h2><p><strong>Previous coverage:</strong> absent in the audited local lesson corpus. <strong>New scope:</strong> bounded introductory-to-practical automation, not a second agent framework curriculum.</p><ul><li><a href="./n8n/">Items, expressions, triggers and control flow</a>: actual item envelopes, current versus linked items, per-item/all-items Code modes, branching/merge and subworkflow contract; prerequisite JSON/data ownership.</li><li><a href="./n8n/integration.html">Webhook/service integration</a>: test versus production URLs, separate inbound/outbound credentials, normalized body/projection, fixed destination and stable business-event identity; prerequisite HTTP and application authorization.</li><li><a href="./n8n/operations.html">Errors/testing/operations</a>: bounded retry/error workflow policy, execution history, pinning versus integration, timeout/replay, deployment database/key/backup ownership and edition/version limits.</li><li><a href="./../workbench/applied-ai/n8n/">Workbench</a>: executable transformation and local HTTP adapter checks. <a href="./../practice/applied-ai/n8n-integration.html">N8N-P01</a> requires actual test-webhook/credential/subworkflow/history observations separately. No n8n engine was installed, workflow published or paid/external action triggered.</li></ul><p>Reference release 2.44.7 and official documentation were checked on 2026-10-27. Current docs may describe newer features; deployment must recheck the installed release/node/edition rather than assume this review tested every UI or hosting option.</p><h2 id="boundaries-of-completion" tabindex="-1"><span class="hub-section-number">7 </span>Boundaries of completion <a class="header-anchor" href="#boundaries-of-completion" aria-label="Permalink to “7 Boundaries of completion”">​</a></h2><p>All essential concepts above have an explanation, worked boundary and ready-to-use practice specification. Optional MCP, ETL/Streamlit, graph databases, multimodal/training/adaptation, distributed workers and hosted products retain their original scope; their source locations were preserved/moved without a new full integration claim. The <a href="./../workbench/applied-ai/">workbench</a> records what actually runs. No learner mastery or historical task completion is inferred.</p>',53)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
